import sys
import math


def main():
    data = sys.stdin.buffer.read()
    d = {}
    get = d.get
    lines = data.split(b'\n')
    for line in lines[1:]:
        if not line:
            continue
        _, c, v = line.split(b',')
        lst = get(c)
        if lst is None:
            d[c] = [float(v)]
        else:
            lst.append(float(v))
    out = []
    for k in sorted(d):
        out.append(k.decode() + ',%.2f' % math.fsum(d[k]))
    if out:
        sys.stdout.write('\n'.join(out) + '\n')


main()
